#!/usr/bin/env bash
# Reproduce S5 v2x-track submission 's5' (model-v2x-track/routed-g5): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-v2x-track/routed-g5/submissions/2026-10-11_s5/v2x_s5_submission.zip (md5 e5b258652c9aa0f783f3cdfbd614d687).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-g5/test/reproduce_s5.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-v2x-track/routed-g5/test/output/repro_s5
mkdir -p $OUT
# member pv_tta: model-v2x-track/pvrcnnpp-g1v3, checkpoint md5 d6018accd31346e39ca127d9bb923291
python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-g1v3 --ckpt model-v2x-track/pvrcnnpp-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pvrcnnpp-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pv_tta.json
# member pvros_tta: model-v2x-track/pvrcnnpp-ros-g1v3, checkpoint md5 eea352738f9a0d47a55b617828f46d01
python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-ros-g1v3 --ckpt model-v2x-track/pvrcnnpp-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pvrcnnpp-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pvros_tta.json
# member ut_tta: model-v2x-track/pointpillars-ut, checkpoint md5 2081ca05e3326bfdbf27794239cdf172
python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pointpillars-ut/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_ut_tta.json
# member vrgb_tta: model-v2x-track/voxelrcnn-gblobs-g1v3, checkpoint md5 f028ceffefe40e05b8eaa68197968ab6
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-gblobs-g1v3 --ckpt model-v2x-track/voxelrcnn-gblobs-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-gblobs-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrgb_tta.json
# member vrros_tta: model-v2x-track/voxelrcnn-ros-g1v3, checkpoint md5 5677c039b8cc33a058b045f732c687de
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v3 --ckpt model-v2x-track/voxelrcnn-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros_tta.json
python common/tools/route_predictions.py merge model-v2x-track/routed-g5 --pred pv_tta=$OUT/predictions_pv_tta.json --pred pvros_tta=$OUT/predictions_pvros_tta.json --pred ut_tta=$OUT/predictions_ut_tta.json --pred vrgb_tta=$OUT/predictions_vrgb_tta.json --pred vrros_tta=$OUT/predictions_vrros_tta.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-v2x-track/routed-g5 --tag s5 --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/v2x-track/pcdet/g1-v3/points" ]; then SYN=(--syn-split val --syn-list model-v2x-track/routed-g5/submissions/2026-10-11_s5/synthetic_ids.txt); else SYN=(--syn-zip model-v2x-track/routed-g5/submissions/2026-10-11_s5/v2x_s5_submission.zip --syn-list model-v2x-track/routed-g5/submissions/2026-10-11_s5/synthetic_ids.txt); fi
python common/tools/package_submission.py model-v2x-track/routed-g5 --tag repro-s5 --pred $OUT/predictions.json --synthetic pcdet/g1-v3 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of s5' --reproduction
Z=model-v2x-track/routed-g5/test/output/repro-s5/submission.zip
python common/tools/check_submission.py --track v2x $Z --official
python common/tools/reproduce_submission.py model-v2x-track/routed-g5 --tag s5 --compare-zip $Z     # predictions and frames against the scored zip
